    if not state["seeds"]:
        return "STAY"
    x, y = state["me"]
    fx, fy = state["seeds"][0]
    order = []
    if fx != x:
        order.append("E" if fx > x else "W")
    if fy != y:
        order.append("S" if fy > y else "N")
    for d in order:
        nx = x + {"E": 1, "W": -1}.get(d, 0)
        ny = y + {"S": 1, "N": -1}.get(d, 0)
        if [nx, ny] not in state["walls"]:
            return d
    return "STAY"

