DIRS = {"N": (0, -1), "E": (1, 0), "S": (0, 1), "W": (-1, 0)}

def neighbours(cell, state):
    x, y = cell
    out = []
    for name, (dx, dy) in DIRS.items():
        nx, ny = x + dx, y + dy
        if 0 <= nx < state["size"] and 0 <= ny < state["size"] and [nx, ny] not in state["walls"]:
            out.append((name, (nx, ny)))
    return out

def distances(start, state):
    """Steps from start to every reachable cell (breadth-first search)."""
    dist = {tuple(start): 0}
    todo = [tuple(start)]
    for cell in todo:
        for _, nxt in neighbours(cell, state):
            if nxt not in dist:
                dist[nxt] = dist[cell] + 1
                todo.append(nxt)
    return dist

def play(state):
    if not state["seeds"]:
        return "STAY"
    goal = tuple(state["seeds"][0])
    dist = distances(goal, state)          # steps from the flag to every cell
    me = tuple(state["me"])
    options = neighbours(me, state)
    if not options:
        return "STAY"
    return min(options, key=lambda n: dist.get(n[1], 999))[0]

